export (NodePath) var objectPath

onready var animaPlayer = $AnimationPlayer
onready var object = get_node_or_null(objectPath)

func _on_AnimationPlayer_animation_started(anim_name):
	if anim_name in [\"sweat\", \"angry\"]:
		var direction
		var emotive_parent := get_parent()
		while !emotive_parent.has_method(\"get_direction\"):
			emotive_parent = emotive_parent.get_parent()
		if emotive_parent.has_method(\"get_direction\"):
			direction = emotive_parent.get_direction()
		if direction.x < 0:
			scale.x = -1
	else:
		scale.x = 1

func set_bubble_offset():
	position.y = -(object.texture.get_height() / object.vframes + 8)
	#print(position.y)
